const lines = [];
let line;
while ((line = readLine()) !== null) lines.push(line);
const tok = lines.join(' ').split(/\s+/).filter(s => s.length).map(Number);
const n = tok[0], T = tok[1];
const coins = tok.slice(2, 2 + n);
const INF = 1e9;
const dp = new Array(T + 1).fill(INF);
dp[0] = 0;
for (let c = 1; c <= T; c++) {
  for (const k of coins) if (k <= c && dp[c - k] + 1 < dp[c]) dp[c] = dp[c - k] + 1;
}
console.log(dp[T] < INF ? dp[T] : -1);

solutions.java:
import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt(), T = sc.nextInt();
        int[] coins = new int[n];
        for (int i = 0; i < n; i++) coins[i] = sc.nextInt();
        int INF = 1_000_000_000;
        int[] dp = new int[T + 1];
        Arrays.fill(dp, INF);
        dp[0] = 0;
        for (int c = 1; c <= T; c++)
            for (int k : coins)
                if (k <= c && dp[c - k] + 1 < dp[c]) dp[c] = dp[c - k] + 1;
        System.out.println(dp[T] < INF ? dp[T] : -1);
    }
}

