#include <bits/stdc++.h>
using namespace std;
int main() {
    int n, T;
    scanf("%d %d", &n, &T);
    vector<int> coins(n);
    for (auto& k : coins) scanf("%d", &k);
    const int INF = 1000000000;
    vector<int> dp(T + 1, INF);
    dp[0] = 0;
    for (int c = 1; c <= T; c++)
        for (int k : coins)
            if (k <= c && dp[c - k] + 1 < dp[c]) dp[c] = dp[c - k] + 1;
    printf("%d\n", dp[T] < INF ? dp[T] : -1);
    return 0;
}
